import { emit } from './shared'; const instances=new WeakMap<HTMLElement,Tabs>();
export class Tabs {readonly element!:HTMLElement;private tabs!:HTMLButtonElement[];private abort=new AbortController();
  constructor(element:HTMLElement){const current=instances.get(element);if(current)return current;this.element=element;this.tabs=[...element.querySelectorAll<HTMLButtonElement>('[role="tab"]')];this.tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>this.select(index),{signal:this.abort.signal});tab.addEventListener('keydown',e=>this.onKey(e,index),{signal:this.abort.signal})});instances.set(element,this)}
  select(index:number){const tab=this.tabs[index];if(!tab||!emit(this.element,'beforechange',this,tab,true))return;this.tabs.forEach((item,i)=>{const selected=i===index;item.setAttribute('aria-selected',String(selected));item.tabIndex=selected?0:-1;const panel=this.element.ownerDocument.getElementById(item.getAttribute('aria-controls')??'');if(panel)panel.hidden=!selected});emit(this.element,'change',this,tab)}
  private onKey(event:KeyboardEvent,index:number){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const rtl=getComputedStyle(this.element).direction==='rtl';let next=event.key==='Home'?0:event.key==='End'?this.tabs.length-1:event.key==='ArrowRight'?(rtl?index-1:index+1):(rtl?index+1:index-1);next=(next+this.tabs.length)%this.tabs.length;this.select(next);this.tabs[next]?.focus()}
  destroy(){this.abort.abort();instances.delete(this.element)} static get(element:HTMLElement){return instances.get(element)} }
