export interface ToastOptions{duration?:number;politeness?:'polite'|'assertive'}
export class Toast {readonly element:HTMLElement;private timer?:number;constructor(message:string,options:ToastOptions={}){let region=document.querySelector<HTMLElement>('[data-nx-toast-region]');if(!region){region=document.createElement('div');region.className='nx-toast-region';region.dataset.nxToastRegion='';region.setAttribute('aria-live',options.politeness??'polite');region.setAttribute('aria-atomic','false');document.body.append(region)}this.element=document.createElement('div');this.element.className='nx-toast';this.element.setAttribute('role','status');this.element.textContent=message;region.append(this.element);const duration=options.duration??5000;if(duration>0)this.timer=window.setTimeout(()=>this.destroy(),duration)}destroy(){if(this.timer)clearTimeout(this.timer);this.element.remove()}static show(message:string,options?:ToastOptions){return new Toast(message,options)}}
